// SPDX-License-Identifier: MIT
// Table of embedded shader sources, generated by scripts/embed_shaders.py
// into $(BUILD)/gen/od_shaders.cpp.
#ifndef OD_SHADERS_H
#define OD_SHADERS_H

namespace od {

struct ShaderUnit {
  const char* name;    // file name in core/shaders, e.g. "ingest_buffer.metal"
  const char* source;  // common.metal + resolved includes + the file
  int mathMode;        // 0 safe, 1 relaxed, 2 fast
};

struct ShaderKernel {
  const char* function;  // kernel entry point name (globally unique)
  int unit;              // index into kShaderUnits
};

extern const ShaderUnit kShaderUnits[];
extern const int kShaderUnitCount;
extern const ShaderKernel kShaderKernels[];
extern const int kShaderKernelCount;

}  // namespace od

#endif
